//
// iq_tables.h - the lookup grids of the IQ1 / IQ2 / IQ3 GGUF formats, in src/quant/iq_tables.cpp (generated by
// tools/gen_iq_tables.py). The grids are format data: a file written in one of these formats decodes correctly only with
// exactly these numbers. Each entry packs byte values lowest byte first: entry e, position j is (e >> 8j) & 0xFF
// (signed for the IQ1 grid).
#pragma once

#include <cstdint>

namespace pelias::quant::iq {

extern const std::uint8_t kSigns[128];  // 7-bit sign pattern -> 8 sign bits (bit 7 = parity)
extern const std::uint8_t kMask[8];     // 1 << j

extern const std::uint64_t kIq2xxsGrid[256];
extern const std::uint64_t kIq2xsGrid[512];
extern const std::uint64_t kIq2sGrid[1024];
extern const std::uint32_t kIq3xxsGrid[256];
extern const std::uint32_t kIq3sGrid[512];
extern const std::uint64_t kIq1sGrid[2048];

}  // namespace pelias::quant::iq
